from functools import lru_cache
class Solution:
    def minimumOperationsToMakeEqual(self, x, y):
        @lru_cache(maxsize=None)
        def f(v):
            if v <= y:
                return y - v
            r11, r5 = v % 11, v % 5
            return min(
                v - y,
                1 + f(v - 1),
                r11 + 1 + f(v // 11),
                (11 - r11) + 1 + f(v // 11 + 1),
                r5 + 1 + f(v // 5),
                (5 - r5) + 1 + f(v // 5 + 1),
            )
        return f(x)

