class Solution {
    int y;
    unordered_map<int,int> memo;
    int f(int v) {
        if (v <= y) return y - v;
        auto it = memo.find(v);
        if (it != memo.end()) return it->second;
        int r11 = v % 11, r5 = v % 5;
        int best = v - y;
        best = min(best, 1 + f(v - 1));
        best = min(best, r11 + 1 + f(v / 11));
        best = min(best, (11 - r11) + 1 + f(v / 11 + 1));
        best = min(best, r5 + 1 + f(v / 5));
        best = min(best, (5 - r5) + 1 + f(v / 5 + 1));
        memo[v] = best;
        return best;
    }
public:
    int minimumOperationsToMakeEqual(int x, int yy) {
        y = yy;
        memo.clear();
        return f(x);
    }
};

