class Solution {
    private int y;
    private Map<Integer, Integer> memo;
    private int f(int v) {
        if (v <= y) return y - v;
        Integer cached = memo.get(v);
        if (cached != null) return cached;
        int r11 = v % 11, r5 = v % 5;
        int best = v - y;
        best = Math.min(best, 1 + f(v - 1));
        best = Math.min(best, r11 + 1 + f(v / 11));
        best = Math.min(best, (11 - r11) + 1 + f(v / 11 + 1));
        best = Math.min(best, r5 + 1 + f(v / 5));
        best = Math.min(best, (5 - r5) + 1 + f(v / 5 + 1));
        memo.put(v, best);
        return best;
    }
    public int minimumOperationsToMakeEqual(int x, int yy) {
        y = yy;
        memo = new HashMap<>();
        return f(x);
    }
}

