var minimumOperationsToMakeEqual = function(x, y) {
    const memo = new Map();
    const f = (v) => {
        if (v <= y) return y - v;
        if (memo.has(v)) return memo.get(v);
        const r11 = v % 11, r5 = v % 5;
        const best = Math.min(
            v - y,
            1 + f(v - 1),
            r11 + 1 + f(Math.floor(v / 11)),
            (11 - r11) + 1 + f(Math.floor(v / 11) + 1),
            r5 + 1 + f(Math.floor(v / 5)),
            (5 - r5) + 1 + f(Math.floor(v / 5) + 1)
        );
        memo.set(v, best);
        return best;
    };
    return f(x);
};
